struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float metaball(float2 p, float2 center, float radius)
{
    float d = length(p - center);
    return radius * radius / (d * d + 0.001);
}

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001;
    float2 uv = i.uv * 2.0 - 1.0;
    float aspect = resolution_x / max(1.0, resolution_y);
    uv.x *= aspect;
    float field = 0.0;
    field += metaball(uv, float2(sin(t * 0.7) * 0.4, cos(t * 0.5) * 0.6), 0.3);
    field += metaball(uv, float2(cos(t * 0.4) * 0.5, sin(t * 0.8) * 0.5 + 0.2), 0.25);
    field += metaball(uv, float2(sin(t * 0.6 + 2.0) * 0.3, cos(t * 0.3) * 0.7 - 0.1), 0.35);
    field += metaball(uv, float2(cos(t * 0.9) * 0.6, sin(t * 0.4 + 1.0) * 0.4), 0.2);
    field += metaball(uv, float2(sin(t * 0.3 + 4.0) * 0.2, cos(t * 0.7 + 2.0) * 0.5 - 0.3), 0.28);
    float blob = smoothstep(0.9, 1.1, field);
    float3 bgCol = float3(0.1, 0.0, 0.15);
    float3 blobCol = lerp(float3(0.9, 0.2, 0.0), float3(1.0, 0.8, 0.0), saturate(field - 1.0));
    float3 col = lerp(bgCol, blobCol, blob);
    float glow = smoothstep(0.6, 1.0, field) * (1.0 - blob);
    col += float3(0.4, 0.05, 0.1) * glow;
    return float4(col, 1.0);
}
